<script setup>
import { ref } from 'vue';
import InputError from './InputError.vue';

defineEmits(['update:modelValue']);

const input = ref(null);

</script>

<template>
    <div class="form-group">
        <label v-if="label" :for="name">{{ label }}</label>
        <input class="form-control" :type="type" :value="modelValue" :name="name" :id="name"
            @input="$emit('update:modelValue', $event.target.value)" ref="input" :placeholder="placeholder"
            :autocomplete="computedAutoComplete" :disabled="disabled" />

        <input-error v-if="typeof(errors) == 'string'" :message="errors"/>
        <input-error v-else v-for="(error, index) in errors" :key="index" :message="error"/>
    </div>
</template>

<script>
export default {
    props: {
        modelValue: {
            type: String,
            required: false,
        },
        name: {
            type: String,
            required: true,
        },
        type: {
            type: String,
            required: false,
            default: 'text',
        },
        placeholder: {
            type: String,
            required: false,
        },
        autocomplete: {
            type: String,
            required: false,
        },
        label: {
            type: String,
            required: false,
        },
        disabled: {
            type: Boolean,
            required: false,
            default: false,
        },
        errors: {
            type: [Object, String, Array],
            required: false,
            default: () => ({}),
        },
    },
    computed: {
        computedAutoComplete() {
            return this.autocomplete || this.name;
        },
    },
}
</script>
